import {
  ConstantTypes,
  type NodeTransform,
  NodeTypes,
  type SimpleExpressionNode,
  type SourceLocation,
  createSimpleExpression,
} from '@vue/compiler-core'
import { parseStringStyle } from '@vue/shared'
import {
  type DeepSelectorTokens,
  createDeepSelectorTokens,
} from '../parserOptions'

// Parse inline CSS strings for static style attributes into an object.
// This is a NodeTransform since it works on the static `style` attribute and
// converts it into a dynamic equivalent:
// style="color: red" -> :style='{ "color": "red" }'
// It is then processed by `transformElement` and included in the generated
// props.
export const transformStyle: NodeTransform = node => {
  if (node.type === NodeTypes.ELEMENT) {
    node.props.forEach((p, i) => {
      if (p.type === NodeTypes.ATTRIBUTE && p.name === 'style' && p.value) {
        // replace p with an expression node
        node.props[i] = {
          type: NodeTypes.DIRECTIVE,
          name: `bind`,
          arg: createSimpleExpression(`style`, true, p.loc),
          exp: parseInlineCSS(p.value.content, p.loc),
          modifiers: [],
          loc: p.loc,
        }
      }
    })
  }
}

const parseInlineCSS = (
  cssText: string,
  loc: SourceLocation,
): SimpleExpressionNode => {
  const normalized = parseStringStyle(cssText)
  return createSimpleExpression(
    JSON.stringify(normalized),
    false,
    loc,
    ConstantTypes.CAN_STRINGIFY,
  )
}

export class NestedNodeTypes {
  constructor(
    public nestedType: string,
    public declType: string,
  ) {}
}

export interface NestedSelectorParts extends DeepSelectorTokens {
  nodeTypes: NestedNodeTypes
}

export function createNestedSelectorParts(): NestedSelectorParts {
  const tokens = createDeepSelectorTokens()
  return {
    nodeTypes: new NestedNodeTypes('rule', 'decl'),
    deepSyntax: tokens.deepSyntax,
    tokens: tokens.tokens,
    deepPseudos: tokens.deepPseudos,
  }
}

