const processedRules = new WeakSet<Rule>()

function processNestedAtRule(
  atRule: AtRule,
  rewriter: ScopedSelectorRewriter,
  units: SelectorRewriteUnits,
) {
  let parent: Container | undefined = atRule.parent
  let nestedInRule = false
  while (parent && parent.type !== 'root') {
    if (parent.type === 'rule') {
      nestedInRule = true
      break
    }
    if (parent.type === 'atrule' && /-?keyframes$/.test(parent.name)) {
      return
    }
    parent = parent.parent
  }
  if (!nestedInRule || !atRule.nodes) {
    return
  }

  const nodes = atRule.nodes.filter(
    node => node.type === units.nodeTypes.declType || node.type === 'comment',
  )
  if (!nodes.some(node => node.type === units.nodeTypes.declType)) {
    return
  }

  for (const node of nodes) {
    atRule.removeChild(node)
  }
  const hostRule = new Rule({
    nodes,
    selector: units.wrap.hostSelector,
  })
  atRule.prepend(hostRule)
  processRule(hostRule, rewriter, units)
}

